  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Convert r = 4 sin θ to Cartesian form.', 'r² = 4r sin θ, so x² + y² = 4y (a circle centred at (0, 2)).', 16),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Convert x² + y² = 9 to polar form.', 'r = 3.', 17),
