  ('Further Mathematics', 'OCR A', 'alevel', '1.4', 'Further Calculus', 'What is a Maclaurin series?', 'f(x) = f(0) + f''(0)x + f''''(0)x²/2! + f''''''(0)x³/3! + …', 24),
